{
    double n, e;
    adcs_vec3_t capped;
    unint32 clean_next;
    gr_mode_t mode_next;
    int have_sample;

    int en = gr_input.enable;
    const adcs_vec3_t *r = gr_input.rate_rad_s;

    /* Disabled: NOMINAL, clean to zero, vector zero */
    if (!en) {
        gr_output.mode = GR_NOMINAL;
        gr_output.clean = 0U;
        gr_output.norm_rad_s = 0.0;
        gr_output.energy_rad2_s2 = 0.0;
        gr_output.capped_rate_rad_s.x = 0.0;
        gr_output.capped_rate_rad_s.y = 0.0;
        gr_output.capped_rate_rad_s.z = 0.0;
        gr_state.mode = GR_NOMINAL;
        gr_state.clean = 0U;
        return;
    }

    /* 配置合法性 */
    if ((!isfinite(gr_config.recovered_rad_s)) || (!isfinite(gr_config.saturated_rad_s)) ||
        (gr_config.recovered_rad_s < 0.0) ||
        (!(gr_config.recovered_rad_s < gr_config.saturated_rad_s)) ||
        (gr_config.required_clean < 1U) || (gr_config.required_clean > 20U)) {
        gr_state.mode = GR_FAULT;
        gr_state.clean = 0U;
        gr_output.mode = GR_FAULT;
        gr_output.clean = 0U;
        gr_output.norm_rad_s = 0.0;
        gr_output.energy_rad2_s2 = 0.0;
        gr_output.capped_rate_rad_s.x = 0.0;
        gr_output.capped_rate_rad_s.y = 0.0;
        gr_output.capped_rate_rad_s.z = 0.0;
        return;
    }

    /* 样本有效性：非NULL、有限 */
    have_sample = (r != NULL) && adcs_is_finite_vec3(r);
    if (!have_sample) {
        gr_state.mode = GR_FAULT;
        gr_state.clean = 0U;
        gr_output.mode = GR_FAULT;
        gr_output.clean = 0U;
        gr_output.norm_rad_s = 0.0;
        gr_output.energy_rad2_s2 = 0.0;
        gr_output.capped_rate_rad_s.x = 0.0;
        gr_output.capped_rate_rad_s.y = 0.0;
        gr_output.capped_rate_rad_s.z = 0.0;
        return;
    }

    /* 计算测量范数与能量 */
    n = adcs_vec3_norm(r);
    e = adcs_vec3_dot(r, r);

    /* 方向保持限幅到 saturated */
    if (n <= gr_config.saturated_rad_s) {
        capped = *r;
    } else if (n > 0.0 && isfinite(n)) {
        capped = adcs_vec3_scale(r, gr_config.saturated_rad_s / n);
    } else {
        capped = *r;
    }

    /* 规范表：模式与 clean */
    mode_next = gr_state.mode;
    clean_next = gr_state.clean;
    if (n >= gr_config.saturated_rad_s) {
        mode_next = GR_SATURATED;
        clean_next = 0U;
        capped.x = 0.0;
        capped.y = 0.0;
        capped.z = 0.0;
    } else if (n <= gr_config.recovered_rad_s) {
        if (gr_state.mode == GR_SATURATED || gr_state.mode == GR_RECOVERING) {
            clean_next = gr_state.clean + 1U;
            if (clean_next >= gr_config.required_clean) {
                mode_next = GR_NOMINAL;
            } else {
                mode_next = GR_RECOVERING;
            }
        } else if (gr_state.mode == GR_NOMINAL) {
            mode_next = GR_NOMINAL;
            clean_next = gr_state.clean;
        }
    } else {
        /* recovered < n < saturated */
        if (gr_state.mode == GR_SATURATED || gr_state.mode == GR_RECOVERING) {
            mode_next = GR_SATURATED;
            clean_next = 0U;
            capped.x = 0.0;
            capped.y = 0.0;
            capped.z = 0.0;
        } else if (gr_state.mode == GR_NOMINAL) {
            mode_next = GR_NOMINAL;
            clean_next = gr_state.clean;
        }
    }

    gr_state.mode = mode_next;
    gr_state.clean = clean_next;

    gr_output.mode = mode_next;
    gr_output.clean = clean_next;
    gr_output.norm_rad_s = n;
    gr_output.energy_rad2_s2 = e;
    gr_output.capped_rate_rad_s = capped;
}

